function maximumOr(nums, k) {
  const n = nums.length;
  const suffix = new Array(n + 1).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    suffix[i] = suffix[i + 1] | nums[i];
  }
  const shift = BigInt(k);
  let prefix = 0;
  let best = 0n;
  for (let i = 0; i < n; i++) {
    const others = prefix | suffix[i + 1];
    const value = (BigInt(nums[i]) << shift) | BigInt(others);
    if (value > best) {
      best = value;
    }
    prefix |= nums[i];
  }
  return Number(best);
}

