function maximumOr(nums, k) {
  // Try every way to spread at most k doublings over the elements.
  let best = 0n;
  const counts = new Array(nums.length).fill(0);
  const visit = (index, left) => {
    if (index === nums.length) {
      let total = 0n;
      for (let j = 0; j < nums.length; j++) total |= BigInt(nums[j]) * 2n ** BigInt(counts[j]);
      if (total > best) best = total;
      return;
    }
    for (let c = 0; c <= left; c++) {
      counts[index] = c;
      visit(index + 1, left - c);
    }
    counts[index] = 0;
  };
  visit(0, k);
  return Number(best);
}

