function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * 1e9));
    const k = 1 + Math.floor(rand() * 15);
    return [nums, k];
  }
  const n = 1 + Math.floor(rand() * 5);
  const style = rand();
  const top = style < 0.6 ? 16 : style < 0.85 ? 255 : 1e9;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const k = 1 + Math.floor(rand() * 4);
  return [nums, k];
}
